// https://observablehq.com/@tmcw/dithering
export const ditheringFloydSteinberg = (ctx: CanvasRenderingContext2D) => {
    const data = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);
    let clone = new ImageData(
        new Uint8ClampedArray(data.data),
        data.width,
        data.height
    );
    const px = (x: number, y: number) => {
        return x * 4 + y * data.width * 4;
    };
    for (let y = 0; y < data.height; y++) {
        for (let x = 0; x < data.width; x++) {
            let oldPixel = clone.data[px(x, y)];

            // console.log('oldPixel', oldPixel)

            // Floyd–Steinberg dithering algorithm
            let newPixel = oldPixel > 125 ? 255 : 0;

            // console.log('newPixel', newPixel)

            clone.data[px(x, y)] = clone.data[px(x, y) + 1] = clone.data[px(x, y) + 2] = newPixel;

            let quantError = oldPixel - newPixel;

            clone.data[px(x + 1, y)] = clone.data[px(x + 1, y) + 1] = clone.data[px(x + 1, y) + 2] = clone.data[px(x + 1, y)] + (quantError * 7) / 16;

            clone.data[px(x - 1, y + 1)] = clone.data[px(x - 1, y + 1) + 1] = clone.data[px(x - 1, y + 1) + 2] = clone.data[px(x - 1, y + 1)] + (quantError * 3) / 16;

            clone.data[px(x, y + 1)] = clone.data[px(x, y + 1) + 1] = clone.data[px(x, y + 1) + 2] = clone.data[px(x, y + 1)] + (quantError * 5) / 16;

            clone.data[px(x + 1, y + 1)] = clone.data[px(x + 1, y + 1) + 1] = clone.data[px(x + 1, y + 1) + 2] = clone.data[px(x + 1, y + 1)] + (quantError * 1) / 16;
        }
    }
    ctx.putImageData(clone, 0, 0);
};
export const getArrayBinaryImgFromCtx = (ctx: CanvasRenderingContext2D) => {
    const data = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);

    const dd = [];
    let index = 0;

    for (let i = 0; i < data.data.length; i++) {

        let oldPixel = data.data[i * 4];
        const n = oldPixel;

        if (n === 0) {
            dd.push(1);
        } else {
            dd.push(0);
        }
        if (index % 8 === 0) {
            dd.push(' ')
        }
    }
    return dd;
};

// https://en.wikipedia.org/wiki/Ordered_dithering
export const dithering4_4 = (ctx: CanvasRenderingContext2D) => {
    const data = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);

    let clone = new ImageData(
        new Uint8ClampedArray(data.data),
        data.width,
        data.height
    );

    const threshold_map_4x4 = [
        [1, 9, 3, 11],
        [13, 5, 15, 7],
        [4, 12, 2, 10],
        [16, 8, 14, 6]
    ];

    const depth = 32;
    const width = data.width;
    const height = data.height;
    const pixel = data.data;

    for (let y = 0; y < data.height; y++) {
        for (let x = 0; x < data.width; x++) {
            // let oldPixel = clone.data[px(x, y)];

            // 4x4 Bayer ordered dithering algorithm
            let a = (x * height + y) * 4;
            let b = threshold_map_4x4[x % 4][y % 4];
            // clone.data[ a + 0 ] = ( (clone.data[ a + 0 ]+ b) / depth | 0 ) * depth;
            // clone.data[ a + 1 ] = ( (clone.data[ a + 1 ]+ b) / depth | 0 ) * depth;
            // clone.data[ a + 2 ] = ( (clone.data[ a + 2 ]+ b) / depth | 0 ) * depth;
            clone.data[a] = clone.data[a + 1] = clone.data[a + 2] = ((clone.data[a] + b) / depth | 0) * depth;

            //    console.log(clone.data[a])
        }
    }
    ctx.putImageData(clone, 0, 0);
};